function showObject(data){if(view==="Overview"){showOverview(data);return;}if(view==="Rejected Uploads"){showRejected(data);return;}if(view==="Insights"){showInsights(data);return;}if(view==="Administration"){showAdministration(data);return;}if(view==="Audit"){byId("content").replaceChildren(table(data,["timestamp","actor","actor_role","action","resource","result","details"]));return;}if(Array.isArray(data)){showRows(data);return;}const dl=node("dl","");dl.className="detail";for(const [key,value]of Object.entries(data||{})){dl.append(node("dt",key.replaceAll("_"," ")));const dd=node("dd","");dd.append(node(typeof value==="object"?"pre":"span",valueText(value)));dl.append(dd);}byId("content").replaceChildren(dl);}
