byId("action-form").onsubmit=async e=>{e.preventDefault();byId("submit-action").disabled=true;try{let body,path;const action=byId("action-kind").value;if(["Review Queue","My Work"].includes(view)){body={expected_version:selected.version,status:action,notes:byId("notes").value,resolution_code:byId("resolution").value||null};path=`/v1/reviews/${selected.risk_event_id}/transition`;}else{body={action,notes:byId("notes").value,candidate:action==="REJECT"?null:JSON.parse(byId("candidate").value)};path=`/v1/quarantine/${selected.quarantine_id}/corrections`;}const signature=JSON.stringify(body);if(!mutation||mutation.signature!==signature)mutation={signature,id:crypto.randomUUID()};const outcome=await request(path,{method:"POST",body:JSON.stringify({...body,request_id:mutation.id})});notify(["Review Queue","My Work"].includes(view)?"Review status: "+outcome.data.review_status:"Correction submitted for revalidation. Check the outcome before treating it as accepted.","SUCCESS",view);const caseId=selected?.quarantine_id;await load();if(caseId)await openQuarantine(caseId);}catch(e){error(e);}finally{byId("submit-action").disabled=false;}};
