function showUploadNotice(message,severity,page,id){notify(message,severity,page,id);const box=document.getElementById("upload-notice");const text=document.getElementById("upload-notice-message");const item=node("article",message);item.className="notification "+severity.toLowerCase();text.prepend(item);box.dataset.severity=severity;box.hidden=false;return item;}
