let notices=[],batchSelection=null,uploadReceipts=new Map();
function notify(message,severity="INFO",page=null,id=null){
  severity=severity.toUpperCase();if(!["SUCCESS","INFO","WARNING","ERROR","ACTION_REQUIRED"].includes(severity))severity="INFO";
  const presentation=FinTrustDisplay.notice(message,severity,page?pageLabel(page):null);notices.unshift({id:crypto.randomUUID(),message,severity,page,object:id,...presentation,time:new Date().toISOString(),acknowledged:false});
}
