function heading(panel,title){panel.append(node("h3",title));}
function facts(data){const dl=node("dl","");dl.className="detail";for(const [k,v]of Object.entries(data)){dl.append(node("dt",k.replaceAll("_"," ")),node("dd",FinTrustDisplay.uuid(v)?v:FinTrustDisplay.value(k,v)));}return dl;}
function table(rows,keys,action){if(!rows.length)return node("p",batchSelection?"No rows in this processing outcome.":emptyMessage(view));const box=node("div","");box.className="table-scroll";const t=node("table","");const head=node("tr","");keys.forEach(k=>{const th=node("th","");th.scope="col";const sort=button(labelFor(k),()=>{const sorted=[...rows].sort((a,b)=>String(a[k]??"").localeCompare(String(b[k]??""),undefined,{numeric:true}));box.replaceWith(table(sorted,keys,action));});sort.className="table-sort";th.append(sort);head.append(th);});if(action)head.append(node("th","Action"));t.append(head);for(const row of rows){const tr=node("tr","");for(const k of keys){const val=k==="risk_level"?row.risk?.risk_level||row.risk_level:k==="risk_score"?row.risk?.score??row.risk_score??null:row[k];const td=tableCell(k,val);if(k.includes("status")||k.includes("disposition")||k==="risk_level"){const badge=node("span",FinTrustDisplay.value(k,val));badge.className="status-badge status-"+String(val).toLowerCase();td.replaceChildren(badge);}tr.append(td);}if(action){const td=node("td","");action(td,row);tr.append(td);}wireQueueRow(tr,row);t.append(tr);}box.append(t);return box;}
function secondaryButton(label,action){const b=button(label,action);b.classList.add("secondary-action");return b;}
function riskCount(data,level){return Array.isArray(data.risk_distribution)?data.risk_distribution.filter(r=>String(r.risk_level).toLowerCase()===level.toLowerCase()).reduce((n,r)=>n+Number(r.count),0):null;}
function metricTiles(entries,kind=""){const metrics=node("div","");metrics.className="metrics "+kind;for(const [label,val]of entries){const tile=node("div","");tile.append(node("span",label),node("strong",val===null||val===undefined?"Unavailable":String(val)));metrics.append(tile);}return metrics;}
