function showAdministration(data){const panel=node("section","");panel.append(node("h3","Users"));panel.append(node("p","Manage local users and access. New user records need a separately issued access token. Enterprise sign-in and AWS users are managed separately."));const userList=node("div","");const search=node("input","");search.type="search";search.placeholder="Filter users by name, username, role or status";search.setAttribute("aria-label","Filter users");const render=()=>userList.replaceChildren(table((data.users||[]).filter(u=>[u.username,u.display_name,u.role,u.status].join(" ").toLowerCase().includes(search.value.toLowerCase())),["display_name","username","role","status","last_sign_in_at","credential_provisioned"],(td,u)=>td.append(button("Manage",()=>userEditor(u)))));search.oninput=render;render();panel.append(search,userList);panel.append(button("Add User",()=>userEditor()));heading(panel,"Platform configuration");panel.append(facts({contract_version:data.contract_version,identity:data.identity,live_deployment:data.live_deployment}));byId("content").replaceChildren(panel);}
function userEditor(user={}){const form=node("form","");form.id="user-governance-form";if(user.user_id)form.append(facts({user_id:user.user_id,created_at:user.created_at,last_sign_in_at:user.last_sign_in_at}));const inputs={};for(const field of ["username","display_name","email","role","status","notes"]){const label=node("label",labelFor(field));const input=node(["role","status"].includes(field)?"select":"input","");input.name=field;input.required=field!=="email";if(field==="email")input.type="email";if(field==="role"&&!user.role){const placeholder=node("option","Choose a role");placeholder.value="";input.append(placeholder);}if(field==="role")for(const role of ["Admin","Risk/Compliance Analyst","Read-only/Auditor","Maintainer"]){const option=node("option",roleLabel(role));option.value=role;input.append(option);}if(field==="status")for(const value of ["ACTIVE","DISABLED"])input.append(node("option",value));if(user[field])input.value=user[field];if(field==="username"&&user.username)input.readOnly=true;label.append(input);form.append(label);inputs[field]=input;}const submit=node("button","Save User");submit.type="submit";form.append(submit,button("Cancel",()=>load()));form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const body=Object.fromEntries(Object.entries(inputs).map(([k,input])=>[k,input.value]));if(!body.email)body.email=null;await request("/v1/administration/users",{method:"POST",body:JSON.stringify(body)});notify("User changes saved.","SUCCESS","Administration");await load();}catch(e){error(e);}finally{submit.disabled=false;}};byId("content").replaceChildren(form);}

