const next=node('div','');if(principal.role==='Admin')next.append(node('p','Manage assignment only. Financial review decisions require the assigned Analyst.'));else if(principal.role==='Read-only/Auditor')next.append(node('p','Read-only evidence. Notes and financial decisions are disabled.'));else if(d.reviewer_subject&&d.reviewer_subject!==principal.subject)next.append(node('p','Assigned to '+(d.assignee_label||d.reviewer_subject)+'. Review the evidence or ask an Administrator to reassign this review.'));else if(d.allowed_actions.claim)next.append(node('p','Claim review to record notes and choose an outcome.'));
