function riskRuleLabel(rule){return {AMOUNT_RISK:'Amount risk',HIGH_AMOUNT:'Amount risk (V1)',VERY_HIGH_AMOUNT:'Very high amount (V1)',HIGH_VELOCITY:'High velocity',CROSS_BORDER:'Cross-border',POSSIBLE_DUPLICATE_CHARGE:'Possible duplicate',TRANSFER:'Transfer (V1)',MERCHANT_MARKER:'Merchant marker (V1)'}[rule]||rule;}
function riskComponentEvidence(risk,signals=[]){
 const panel=node('div','');panel.className='risk-components';
 const version=risk.rule_version||'Not recorded';panel.append(investigationFacts({rule_version:version,evaluated_at:risk.evaluated_at}));
 panel.append(node('p','Rule-based risk score. This percentage represents the configured risk score, not the probability of fraud.'));
 let components=risk.components;
 if(!components){
  panel.append(node('p',Object.keys(risk).length?'Historical assessment — shown as recorded. V2 weights have not been applied. Missing measurements are not reconstructed.':'No recorded component measurements. Missing evidence is not reconstructed.'));
  const original=signals.length?signals:risk.triggered_rules||[],amount=original.filter(c=>['HIGH_AMOUNT','VERY_HIGH_AMOUNT'].includes(c.rule));
  components=original.filter(c=>!['HIGH_AMOUNT','VERY_HIGH_AMOUNT'].includes(c.rule));
  if(amount.length)components.unshift({rule:'AMOUNT_RISK',label:'Amount risk (V1)',points:amount.reduce((n,c)=>n+Number(c.points||0),0),triggered_value:amount[0].triggered_value,reason:amount.map(c=>c.reason).join('; '),context:'Original overlapping V1 amount contribution retained.',created_at:amount[0].created_at});
 }
 for(const c of components){
  const section=node('section','');section.className='risk-component';section.dataset.rule=c.rule;
  section.append(node('h4',(c.label||riskRuleLabel(c.rule))+' · +'+c.points),node('p',c.rule==='POSSIBLE_DUPLICATE_CHARGE'&&c.triggered===false?'No matching distinct-source charge in the configured time window.':c.reason||'Original explanation unavailable.'));
  const values={points_contributed:c.points};
  if(c.rule==='AMOUNT_RISK'){
   values.observed_amount=c.triggered_value??'Not captured in scoring evidence';values.currency=c.currency;
   const b=c.amount_band;values.amount_band=b?(b.lower_inclusive?'At most '+b.upper:'Greater than '+b.lower+(b.upper?' and at most '+b.upper:'')):'Original V1 bands; see technical evidence';
  }else if(c.rule==='HIGH_VELOCITY'){
   const minutes=c.window_seconds?c.window_seconds/60:null;
   values.observed_count=c.triggered_value??'Not captured in scoring evidence';
   values.configured_threshold=c.threshold!=null?'More than '+c.threshold+' transactions'+(minutes?' within '+minutes+' minutes':''): 'Not captured in scoring evidence';
   values.account_id=c.account_id;values.observed_window_start=c.observed_window_start;values.observed_window_end=c.observed_window_end;
   values.closed_window_start=c.window_start;values.closed_window_end=c.window_end;
   values.includes_current=c.includes_current;
  }else if(c.rule==='CROSS_BORDER'){
   values.transaction_country=c.triggered_value??'Not captured in scoring evidence';values.domestic_country=c.domestic_country||c.threshold||'Not captured in scoring evidence';
   if(c.explicit_cross_border!==undefined)values.explicit_cross_border=c.explicit_cross_border;
  }else if(c.rule==='POSSIBLE_DUPLICATE_CHARGE'){
   values.matches_shown=c.triggered_value??c.matching_transaction_ids?.length??'Not captured in scoring evidence';
   values.matching_fields=c.matching_fields?.join(', ')||'Not captured in scoring evidence';
   values.time_proximity=c.window_seconds!=null?'At most '+c.window_seconds+' seconds on either side of event time':'Not captured in scoring evidence';
   values.distinct_source_references=c.distinct_source_references;
  }else{values.measured_value=c.triggered_value??'Not captured in scoring evidence';values.threshold=c.threshold??'Not captured in scoring evidence';}
  values.evaluated_at=c.evaluated_at||risk.evaluated_at||'Not recorded';if(c.created_at)values.recorded_at=c.created_at;values.rule_version=c.rule_version||version;
  if(c.triggered!==undefined)values.component_status=c.triggered?'Triggered':'Not triggered';
  section.append(investigationFacts(values));
  if(c.matching_transactions?.length)section.append(table(c.matching_transactions,['tx_id','source_transaction_id','tx_date','seconds_apart']));
  for(const id of c.matching_transaction_ids||[])section.append(secondaryButton('Related '+FinTrustDisplay.reference('tx_id',id),()=>openTransaction(id)));
  panel.append(section);
 }
 if(!components.length)panel.append(node('p','No risk rules triggered.'));
 const technical=node('details','');technical.append(node('summary','Technical rule evidence'),table(risk.triggered_rules||[],['rule','points','reason','triggered_value','threshold','evaluated_at','rule_version']));panel.append(technical);
 return panel;
}

function riskScore(raw,level){
 const box=node("span","");box.className="risk-score";
 const score=raw===null||raw===undefined||raw===""?null:Number(raw);
 if(score===null||!Number.isFinite(score)||score<0||score>100){box.classList.add("unassessed");box.textContent="Not recorded";box.title="No recorded risk assessment. This is not a zero score.";return box;}
 box.append(node("strong",String(score)+"%"));if(level)box.append(node("small"," — "+String(level).toUpperCase()));
 const track=node("span","");track.className="score-track";track.setAttribute("aria-hidden","true");const bar=node("span","");bar.style.width=score+"%";track.append(bar);box.append(track);
 box.title="Rule-based risk score. This percentage represents the configured risk score, not the probability of fraud.";return box;
}
function riskDistribution(rows){
 const panel=node("section","");panel.className="insight-chart risk-distribution";heading(panel,"Risk distribution");
 const total=rows.reduce((n,r)=>n+Number(r.count),0);if(!total){panel.append(node("p","No assessed transactions in this scope."));return panel;}
 const layout=node("div","");layout.className="distribution-layout";
 const ns="http://www.w3.org/2000/svg",svg=document.createElementNS(ns,"svg");svg.setAttribute("viewBox","0 0 180 180");svg.setAttribute("role","img");svg.setAttribute("aria-label",`Risk distribution: ${total} assessed transactions. Exact counts follow.`);
 const add=(tag,attrs,text)=>{const el=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));if(text!==undefined)el.textContent=text;svg.append(el);return el;};
 add("circle",{cx:90,cy:90,r:65,fill:"none",stroke:"#edf1f5","stroke-width":18});let offset=0;const circumference=2*Math.PI*65;
 const colors={Low:"#16816b",Medium:"#d49a25",High:"#c84345"},legend=node("div","");legend.className="distribution-legend";
 for(const r of rows){const length=Number(r.count)/total*circumference;add("circle",{cx:90,cy:90,r:65,fill:"none",stroke:colors[r.label]||"#718293","stroke-width":18,"stroke-dasharray":`${length} ${circumference-length}`,"stroke-dashoffset":-offset,transform:"rotate(-90 90 90)"});offset+=length;const item=node("p","");const dot=node("span","");dot.className="legend-dot";dot.style.background=colors[r.label]||"#718293";item.append(dot,node("span",r.label),node("strong",String(r.count)));legend.append(item);}
 add("text",{x:90,y:91,"text-anchor":"middle","font-size":30,"font-weight":700,fill:"#1b3444"},total);add("text",{x:90,y:112,"text-anchor":"middle","font-size":12,fill:"#647584"},"assessed");layout.append(svg,legend);panel.append(layout,table(rows,["label","count"]));return panel;
}
